// The pet system data (public/data/pets.json, generated by
// scripts/gen_petdata.py from the shipped client tables - see
// zu-re/docs/pet-system.md).  Types + the lazy cached loader + the pure
// helpers the pet UI needs.

export type PetSpecies = {
  id: number;
  name: string;
  // the icon basename in the pet sprite sheet; null = the extraction has no
  // bmp for it (event tortoises) - the UI renders a name-only row
  icon: string | null;
  // the aptitude range the egg tooltip promises: [min, max] (flat: [N, N]),
  // null = no egg range shipped (sorts last; server rolls the real value)
  apt: [number, number] | null;
  // the egg that hatches this species: "Primary" / "Junior" / "Senior" /
  // "Other" (named eggs and random eggs without those words)
  eggKind: string;
};

export type PetGearItem = {
  id: number;
  name: string;
  // 0 eyes / 1 inner bolus / 2 feet accelerator / 3 saddle
  slot: number;
  // the pet level the gear needs (YearsNeed); 0 = not written down
  req: number;
  icon: string | null;
  // the shipped tooltip text (the stat numbers are parsed out of it)
  desc: string;
  atk: number | null;
  pd: number | null;
  md: number | null;
  // feet accelerators only: the speed bonus in %
  speed: number | null;
};

export type PetSpellRank = { id: number; exp: number; effect: number };

export type PetSpell = {
  kind: number;
  name: string;
  icon: string | null;
  desc: string;
  ranks: PetSpellRank[];
};

// [xp, atkMin, atkMax, hp, mp, pd, md] per pet level 0..300 (RACE group 7)
export type PetCurveRow = [number, number, number, number, number, number, number];

export type PetData = {
  species: PetSpecies[];
  gear: PetGearItem[];
  spells: PetSpell[];
  curve: PetCurveRow[];
  // [stage, maxAptitude, the pet level that reaches it] from PETEVOLVE
  evolve: [number, number, number][];
  // false when the group-7 MoveSpeed column held garbage (Speed+ then shows "—")
  movesSane: boolean;
};

let cache: Promise<PetData> | null = null;

export function loadPets(): Promise<PetData> {
  if (!cache) cache = fetch("/data/pets.json").then((r) => r.json() as Promise<PetData>);
  return cache;
}

// The max aptitude a pet of this level can hold: the PETEVOLVE ladder
// (2500 at hatch, +500 per stage, 5000 cap).  (est.) - the client table
// gives the stages; the exact growth between them is not shipped.
export function maxAptitude(level: number): number {
  return Math.min(5000, 2500 + 500 * Math.floor(level / 40));
}

// Species sorted by aptitude, lower first; no-egg-range species last.
export function sortSpecies(species: PetSpecies[]): PetSpecies[] {
  return [...species].sort((a, b) =>
    (a.apt ? a.apt[0] : Infinity) - (b.apt ? b.apt[0] : Infinity) || a.name.localeCompare(b.name));
}

// The highest level requirement among a slot's gear (the pet level input's
// sensible ceiling).
export function maxGearLevel(gear: PetGearItem[]): number {
  return gear.reduce((m, g) => Math.max(m, g.req), 0);
}

// The pet stat rows (zu-re/docs/pet-system.md §8): the RACE group-7 curve at
// the pet level, scaled by aptitude / maxAptitude.  (est.) - the shipped data
// gives the curve and the aptitude ladder but not the client's exact bonus
// formula; the midpoints of the egg ranges stand in for the server's roll.
export type PetStats = {
  hpBonus: number | null;
  mpBonus: number | null;
  atkBonus: number | null;
  pdBonus: number | null;
  mdBonus: number | null;
  // [current (est.), max] for the five aptitude rows; null = no egg range
  apt: [number, number] | null;
};

export function petStats(
  level: number,
  apt: [number, number] | null,
  curve: PetCurveRow[],
): PetStats {
  const row = curve[Math.max(0, Math.min(level, curve.length - 1))];
  const cur = apt ? (apt[0] + apt[1]) / 2 : null;
  const max = maxAptitude(level);
  const b = (v: number) => (cur == null ? null : Math.round((v * cur) / max));
  return {
    hpBonus: b(row[3]),
    mpBonus: b(row[4]),
    atkBonus: b((row[1] + row[2]) / 2),
    pdBonus: b(row[5]),
    mdBonus: b(row[6]),
    apt: cur == null ? null : [cur, max],
  };
}
